<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

const props = defineProps<{ exam: any; attempts: any[]; summary: { total: number; submitted: number; graded: number; pending_review: number; average: number | null } }>();
const search = ref('');
const status = ref('all');
const gradingAnswer = ref<any | null>(null);
const gradeForm = useForm({ score: '' as number | string });
const filteredAttempts = computed(() => props.attempts.filter((attempt) => {
    const name = `${attempt.student?.name ?? ''} ${attempt.student?.nis ?? ''}`.toLowerCase();
    return (!search.value.trim() || name.includes(search.value.trim().toLowerCase())) && (status.value === 'all' || attempt.status === status.value);
}));
const essayAnswers = (attempt: any) => (attempt.answers ?? []).filter((answer: any) => (answer.question_version ?? answer.question)?.type === 'essay');
const openGrade = (answer: any) => { gradingAnswer.value = answer; gradeForm.score = answer.score ?? ''; gradeForm.clearErrors(); };
const saveGrade = () => { if (!gradingAnswer.value) return; gradeForm.post(`/ujian/jawaban/${gradingAnswer.value.id}/nilai`, { preserveScroll: true, onSuccess: () => { gradingAnswer.value = null; } }); };
const publishResults = () => { if (props.summary.pending_review > 0) return; if (window.confirm('Terbitkan hasil ujian dan sinkronkan nilai ke komponen penilaian? Tindakan ini mengunci publikasi hasil.')) router.post(`/ujian/${props.exam.id}/hasil/terbitkan`, {}, { preserveScroll: true }); };
</script>

<template>
    <Head title="Hasil Ujian" />
    <AppLayout>
        <main class="view space-y-6">
            <section class="hero-card result-hero"><div><p class="eyebrow">Asesmen · Hasil CBT</p><h1>{{ exam.title }}</h1><p>Periksa pengumpulan, koreksi esai, dan terbitkan hasil setelah semua jawaban siap.</p></div><div class="actions"><a class="secondary-button" :href="`/ujian/${exam.id}/hasil/export`">Ekspor CSV</a><button class="primary-button" type="button" :disabled="summary.pending_review > 0" @click="publishResults">{{ summary.pending_review ? `${summary.pending_review} esai belum dinilai` : 'Terbitkan hasil' }}</button></div></section>
            <section class="result-stats"><div><span>Total siswa</span><strong>{{ summary.total }}</strong></div><div><span>Sudah mengumpulkan</span><strong>{{ summary.submitted }}</strong></div><div><span>Sudah dinilai</span><strong>{{ summary.graded }}</strong></div><div><span>Rata-rata nilai</span><strong>{{ summary.average === null ? '—' : Number(summary.average).toFixed(2) }}</strong></div></section>
            <section class="panel result-list"><div class="list-toolbar"><div><h2>Daftar pengumpulan</h2><p>{{ filteredAttempts.length }} dari {{ attempts.length }} siswa ditampilkan</p></div><div class="toolbar-fields"><input v-model="search" placeholder="Cari nama atau NIS" aria-label="Cari siswa" /><select v-model="status" aria-label="Filter status"><option value="all">Semua status</option><option value="in_progress">Sedang mengerjakan</option><option value="pending_review">Perlu dinilai</option><option value="graded">Selesai dinilai</option></select></div></div><article v-for="attempt in filteredAttempts" :key="attempt.id" class="attempt-row"><header><div><strong>{{ attempt.student?.name ?? 'Siswa' }}</strong><small>{{ attempt.student?.nis ?? 'NIS tidak tersedia' }}</small></div><div class="attempt-score"><b>{{ attempt.score === null ? '—' : Number(attempt.score).toFixed(2) }}</b><span class="status-badge" :class="`status-${attempt.status}`">{{ attempt.status }}</span></div></header><div class="attempt-meta"><span>Dikirim: {{ attempt.submitted_at ? new Date(attempt.submitted_at).toLocaleString('id-ID') : 'Belum dikirim' }}</span><span>{{ attempt.violation_count }} pelanggaran</span><span v-if="attempt.events?.length">{{ attempt.events.length }} catatan audit</span></div><div v-for="answer in essayAnswers(attempt)" :key="answer.id" class="essay"><div><strong>Esai</strong><p>{{ (answer.question_version ?? answer.question)?.prompt }}</p></div><blockquote>{{ answer.answer || '(kosong)' }}</blockquote><button class="secondary-button" type="button" @click="openGrade(answer)">{{ answer.score === null ? 'Nilai esai' : `Ubah nilai (${answer.score})` }}</button></div></article><p v-if="!filteredAttempts.length" class="empty-state">Belum ada pengumpulan yang sesuai filter.</p></section>
            <Link class="secondary-button back-link" href="/ujian">← Kembali ke daftar ujian</Link>
            <div v-if="gradingAnswer" class="modal-backdrop" role="presentation" @click.self="gradingAnswer = null"><form class="modal-card" @submit.prevent="saveGrade"><div class="modal-heading"><div><p class="eyebrow">Koreksi manual</p><h2>Nilai jawaban esai</h2></div><button class="close-button" type="button" aria-label="Tutup" @click="gradingAnswer = null">×</button></div><p class="prompt-preview">{{ (gradingAnswer.question_version ?? gradingAnswer.question)?.prompt }}</p><blockquote>{{ gradingAnswer.answer || '(kosong)' }}</blockquote><label>Nilai (maks. {{ gradingAnswer.max_points ?? 'sesuai bobot soal' }})<input v-model.number="gradeForm.score" type="number" min="0" step="0.01" required /></label><p v-if="gradeForm.hasErrors" class="error">{{ Object.values(gradeForm.errors)[0] }}</p><div class="modal-actions"><button class="secondary-button" type="button" @click="gradingAnswer = null">Batal</button><button class="primary-button" type="submit" :disabled="gradeForm.processing">{{ gradeForm.processing ? 'Menyimpan…' : 'Simpan nilai' }}</button></div></form></div>
        </main>
    </AppLayout>
</template>

<style scoped>
