dding:1rem;background:#0f172a99}.modal-card{width:min(620px,96vw);display:grid;gap:.8rem;padding:1.3rem;background:#fff;border-radius:1rem}.modal-card label{display:grid;gap:.35rem;font-size:.82rem;font-weight:700}.prompt-preview{font-weight:700}.modal-card blockquote{margin:0;padding:.75rem;border-radius:.6rem;background:#f8fafc;color:#475569;white-space:pre-wrap;overflow-wrap:anywhere}.modal-actions{display:flex;justify-content:flex-end;gap:.55rem}.close-button{border:0;background:transparent;font-size:1.5rem;cursor:pointer}.error{color:#b91c1c;font-size:.82rem}@media(max-width:800px){.result-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.result-hero,.list-toolbar{align-items:stretch;flex-direction:column}.toolbar-fields{width:100%}.toolbar-fields>*{flex:1;min-width:0}}@media(max-width:560px){.result-stats{grid-template-columns:1fr}.attempt-row header{align-items:flex-start;flex-direction:column}.attempt-score{justify-content:space-between;width:100%}}
</style>
